local _b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function b64decode(data)
  data = data:gsub('[^'.._b..'=]', '')
  local t={}
  local n=0
  for i=1,#data,4 do
    local a,b,c,d = data:byte(i,i+3)
    local function v(ch) if ch==61 then return 0 else return _b:find(string.char(ch),1,true)-1 end end
    local A,B,C,D = v(a),v(b),v(c),v(d)
    local triple = A*262144 + B*4096 + C*64 + D
    local c1 = math.floor(triple/65536)%256
    local c2 = math.floor(triple/256)%256
    local c3 = triple%256
    n=n+1; t[n]=string.char(c1)
    if c~=61 then n=n+1; t[n]=string.char(c2) end
    if d~=61 then n=n+1; t[n]=string.char(c3) end
  end
  return table.concat(t)
end
